    public static EzGfxResult EzGfxCRenderAddVertexPipeline<TBinding>(ulong shader, ulong indirect, ReadOnlySpan<TBinding> bindings, uint cullMode, uint frontFace, uint primitiveType, uint blendMode, ReadOnlySpan<byte> pushConstants) where TBinding : IEzGfxBindingInput
    {
        if (bindings.Length > 16) throw new ArgumentException("Too many render bindings.", nameof(bindings));
        if (pushConstants.Length > 128) throw new ArgumentException("Push constants exceed the native limit.", nameof(pushConstants));
        int totalBytes = 0;
        foreach (TBinding binding in bindings)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(binding.Name);
            totalBytes = checked(totalBytes + Utf8ByteCount(binding.Name));
        }
        byte[]? rented = null;
        scoped Span<byte> storage;
        if (totalBytes <= StackAllocationLimit)
        {
            storage = stackalloc byte[totalBytes];
        }
        else
        {
            rented = ArrayPool<byte>.Shared.Rent(totalBytes);
            storage = rented.AsSpan(0, totalBytes);
        }
        Span<EzGfxBinding> nativeBindings = bindings.Length == 0 ? Span<EzGfxBinding>.Empty : stackalloc EzGfxBinding[bindings.Length];
        EzGfxDynamicState dynamicState = new()
        {
            CullMode = cullMode,
            FrontFace = frontFace,
            PrimitiveType = primitiveType,
            BlendMode = blendMode,
        };
        try
        {
            fixed (byte* utf8 = storage)
            fixed (EzGfxBinding* bindingPointer = nativeBindings)
            fixed (byte* pushPointer = pushConstants)
            {
                int offset = 0;
                for (int index = 0; index < bindings.Length; index++)
                {
                    TBinding binding = bindings[index];
                    nativeBindings[index] = new EzGfxBinding
                    {
                        Name = PutUtf8(utf8, ref offset, binding.Name),
                        Structured = binding.Structured,
                        Indirect = binding.Indirect,
                    };
                }
                IntPtr bindingAddress = bindings.Length == 0 ? IntPtr.Zero : (IntPtr)bindingPointer;
                IntPtr pushAddress = pushConstants.Length == 0 ? IntPtr.Zero : (IntPtr)pushPointer;
                return RawEzGfxCRenderAddVertexPipeline(shader, indirect, bindingAddress, checked((uint)bindings.Length), (IntPtr)(&dynamicState), pushAddress, checked((uint)pushConstants.Length));
            }
        }
        finally
        {
            if (rented is not null) ArrayPool<byte>.Shared.Return(rented);
        }
    }

